insert into public.inventory (product_id, warehouse_id, quantity, reserved_quantity, reorder_level, reorder_quantity) select p.id, w.id, 50, 0, 10, 50 from public.products p cross join public.warehouses w where p.sku like 'DANTOWN-CAT-%' and w.is_active on conflict (product_id, variant_id, warehouse_id, location_id) do update set quantity=50, reorder_level=10, reorder_quantity=50, updated_at=timezone('utc', now());
insert into public.inventory (product_id, variant_id, warehouse_id, quantity, reserved_quantity, reorder_level, reorder_quantity) select v.product_id, v.id, w.id, 50, 0, 10, 50 from public.product_variants v join public.products p on p.id=v.product_id cross join public.warehouses w where p.sku like 'DANTOWN-CAT-%' and w.is_active on conflict (product_id, variant_id, warehouse_id, location_id) do update set quantity=50, reorder_level=10, reorder_quantity=50, updated_at=timezone('utc', now());
